using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class SpatialVerify {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("B5_Spatial_Refinement");var guide=root.Find("Spatial_DestinationGuidance");Physics.SyncTransforms();var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_SpatialRefinement/guidance.json"));var routes=new List<object>();int samples=0;foreach(var r in plan["routes"]){int blocked=0,missing=0;var examples=new List<object>();foreach(var q in r["points"]){samples++;var p=new Vector3((float)q[0],-81.99f,(float)q[1]);var hits=Physics.OverlapCapsule(p+Vector3.up*.38f,p+Vector3.up*1.60f,.30f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.enabled&&c.transform.IsChildOf(root)).ToArray();if(hits.Length>0){blocked++;if(examples.Count<4)examples.Add(new{point=V(p),hits=hits.Select(c=>P(c.transform))});}if(!Physics.RaycastAll(p+Vector3.up*.2f,Vector3.down,.5f,~0,QueryTriggerInteraction.Ignore).Any(h=>h.normal.y>.8f&&h.collider.transform.IsChildOf(root)))missing++;}routes.Add(new{id=(string)r["id"],samples=r["points"].Count(),blocked,missing,examples});}
 var meshes=group.GetComponentsInChildren<MeshFilter>().Concat(guide.GetComponentsInChildren<MeshFilter>()).Select(m=>m.sharedMesh).Distinct().ToArray();int degenerate=0;long triangles=0;foreach(var m in meshes){var v=m.vertices;var t=m.triangles;triangles+=t.Length/3;for(int i=0;i<t.Length;i+=3)if(Vector3.Cross(v[t[i+1]]-v[t[i]],v[t[i+2]]-v[t[i]]).sqrMagnitude<1e-22f)degenerate++;}var missingMats=group.GetComponentsInChildren<Renderer>().Concat(guide.GetComponentsInChildren<Renderer>()).Where(r=>r.sharedMaterials.Any(m=>!m)).Select(r=>P(r.transform)).ToArray();
 var result=new{scene=s.path,samples,routes,uniqueMeshes=meshes.Length,triangles,degenerate,missingMats,newMonoBehaviours=group.GetComponentsInChildren<MonoBehaviour>().Select(b=>b.GetType().FullName),lights=root.GetComponentsInChildren<Light>(true).Select(l=>new{path=P(l.transform),position=V(l.transform.position),rotation=V(l.transform.eulerAngles),l.enabled,l.intensity,l.range,l.spotAngle,color=V(new Vector3(l.color.r,l.color.g,l.color.b)),type=l.type.ToString(),shadows=l.shadows.ToString()}),hierarchy=root.GetComponentsInChildren<Transform>(true).Select(t=>new{path=P(t),position=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf})};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_SpatialRefinement/verification.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{samples,routes,meshes=meshes.Length,triangles,degenerate,missingMaterials=missingMats.Length};}
}
